#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""G023: score .9 against stock on the HDD VM (arms S = stock, N = .9 with --db-cache-drop, N0 = .9 without it; fallback B =
stock + monero 0001/0002/0004 in stage 2 if stock does not fit; stage 1 no cap, stage 2 MEM_MAX=1536M), against the
pre-registration in experiments/G023-dot9-vs-stock-hddvm/README.md. G019D's scorer (g019d_score.py) with these arms.

Reads the stage dir's results.txt (RESULT, WINDOW, CACHEDROP lines, labels g023-s<stage>-r<n>-<arm>) and log.txt (BIN_<arm>),
and counts ERROR lines (the level field) in each run dir's monerod.log (the dirs under the run root, matched by label).
The heavy part is windows k=2..7, as kit 13: its rate is 6,000 blocks over the sum of those windows' seconds, its reads the
mean of their read_kB_per_block. A run whose outcome is not ok is listed and left out of the ratios.
Ratios are of medians (2 runs an arm: their mean); "no overlap" when the two arms' ranges are disjoint.
usage: python3 -I g023_score.py <stage dir> <dir holding the run dirs>"""
import os, re, statistics, sys

TOP_HASH = "5a956cc4b1d19d21423fa11292a1c5f2496111e1a7d39562f4d2287284036361"
HEAVY = range(2, 8)
STAGES = {"1": "none", "2": "1536M"}
SHA = {"S": "e2e058db27c4bb94", "N": "c44c62f156ef33c6", "N0": "c44c62f156ef33c6", "B": "9cbc14e01d662007"}
CD_ARMS = ("N",)


def num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def fields(line):
    return dict(m.groups() for m in re.finditer(r"(\S+?)=(\S*)", line))


stage_dir, run_root = sys.argv[1], sys.argv[2]
runs, problems = {}, []
for line in open(os.path.join(stage_dir, "results.txt")):
    kind = line.split(" ", 2)[1] if line.count(" ") >= 2 else ""
    f = fields(line)
    m = re.match(r"g023-s([12])-r(\d)-(S|N0|N|B)$", f.get("label", ""))
    if not m:
        continue
    r = runs.setdefault(f["label"], {"stage": m.group(1), "n": int(m.group(2)), "arm": m.group(3), "win": {}})
    if kind == "RESULT":
        r["f"] = f
    elif kind == "WINDOW":
        r["win"][int(f["k"])] = (num(f.get("secs")), num(f.get("read_kB_per_block")))
    elif kind == "CACHEDROP":
        r["cd"] = f

for lab, r in runs.items():
    d = [x for x in os.listdir(run_root) if x.endswith("-" + lab)]
    if len(d) != 1:
        problems.append("%s: %d run dirs" % (lab, len(d)))
        r["err"] = None
        continue
    p = os.path.join(run_root, d[0], "monerod.log")
    log = open(p, errors="replace").read() if os.path.exists(p) else ""
    r["err"] = sum(1 for l in log.splitlines() if len(l.split("\t")) > 2 and l.split("\t")[2].strip() == "ERROR")  # the level field
    r["cdlog"] = log.count("LMDB page cache drop: on")
    w = r["win"]
    if all(k in w and w[k][0] and w[k][1] is not None for k in HEAVY):
        r["rate"] = 1000 * len(HEAVY) / sum(w[k][0] for k in HEAVY)
        r["kb"] = statistics.mean(w[k][1] for k in HEAVY)
    else:
        r["rate"] = r["kb"] = None
        problems.append("%s: heavy windows missing" % lab)

binl = open(os.path.join(stage_dir, "log.txt")).read()
for a, s in SHA.items():
    if not any(r["arm"] == a for r in runs.values()):
        continue
    if not re.search(r"^BIN_%s \S+ \(%s\)" % (a, s), binl, re.M):
        problems.append("log.txt: BIN_%s is not sha16 %s" % (a, s))

g = lambda r, k: num(r["f"].get(k))
print("%-14s %-7s %4s %9s %9s %8s %9s %9s %8s %8s %6s %5s %5s %4s" % (
    "run", "outcome", "arm", "heavy_b/s", "heavy_kB", "launch_s", "cpu_s", "rssanon", "cg_anon", "refault", "oomk", "cdrop", "ERROR", "hash"))
for lab in sorted(runs, key=lambda l: (runs[l]["stage"], runs[l]["n"])):
    r = runs[lab]; f = r["f"]
    print("%-14s %-7s %4s %9.3f %9.1f %8.1f %9.1f %9s %8s %8s %6s %5s %5s %4s" % (
        lab[5:], f.get("outcome"), r["arm"], r["rate"] or float("nan"), r["kb"] or float("nan"), g(r, "launch_to_top_s"), g(r, "cpu_s"), f.get("rss_anon_max_MB"),
        f.get("cg_anon_max_MB"), f.get("cg_refault_file"), f.get("cg_oom_kill"), r["cdlog"], r["err"],
        "ok" if f.get("hash_at_3113400") == TOP_HASH else "BAD"))


def arm(st, a, fn):
    return [fn(r) for r in runs.values() if r["stage"] == st and r["arm"] == a and r["f"].get("outcome") == "ok"]


def ratio(st, a, b, fn, label):
    x, y = arm(st, a, fn), arm(st, b, fn)
    if not x or not y:
        print("  stage %s %s %s/%s: no ok runs on one side" % (st, label, a, b))
        return None, None
    q = statistics.median(x) / statistics.median(y)
    dis = max(x) < min(y) or max(y) < min(x)
    print("  stage %s %s %s/%s %.3f (%s %s against %s %s; %s)" % (st, label, a, b, q, a, "-".join("%.4g" % v for v in sorted(x)),
          b, "-".join("%.4g" % v for v in sorted(y)), "no overlap" if dis else "overlap"))
    return q, dis


rate = lambda r: r["rate"]
kb = lambda r: r["kb"]
ltop = lambda r: g(r, "launch_to_top_s")
cpu = lambda r: g(r, "cpu_s")
res = {}
base = {}
for st in "12":
    base[st] = "B" if st == "2" and any(r["stage"] == "2" and r["arm"] == "B" for r in runs.values()) else "S"
    print("stage %s (%s), base %s" % (st, STAGES[st], base[st]))
    for a in (base[st], "N", "N0"):
        print("  arm %s: heavy b/s %s; heavy kB/block %s; launch_to_top_s %s; cpu_s %s; rss_anon_max_MB %s" % (
            a, arm(st, a, rate), [round(v, 1) for v in arm(st, a, kb)], arm(st, a, ltop), arm(st, a, cpu),
            arm(st, a, lambda r: g(r, "rss_anon_max_MB"))))
    for a, b in (("N", base[st]), ("N0", base[st]), ("N", "N0")):
        res[(st, a, b, "rate")] = ratio(st, a, b, rate, "heavy rate")
        res[(st, a, b, "ltop")] = ratio(st, a, b, ltop, "launch_to_top_s (time)")
        res[(st, a, b, "cpu")] = ratio(st, a, b, cpu, "cpu_s")

v = {}
def say(h, ok, text):
    v[h] = ok
    print("%s %s: %s" % (h, "met" if ok else "NOT met", text))

def inb(q, lo, hi):
    return q is not None and lo <= q <= hi

for p in problems:
    print("PROBLEM " + p)
allr = list(runs.values())
ok9 = [r for r in allr if r["arm"] in ("N", "N0")]
say("H1", not problems
    and all(r["f"].get("outcome") == "ok" and r["f"].get("hash_at_3113400") == TOP_HASH and r["err"] == 0 for r in ok9)
    and all((r["cdlog"] == 1 and r["cd"].get("on") == "1") if r["arm"] in CD_ARMS else (r["cdlog"] == 0 and r["cd"].get("lines") == "0") for r in allr if r["f"].get("outcome") == "ok")
    and all(r["f"].get("cg_oom_kill") in ("0", "na") for r in ok9),
    "every N and N0 run ok with the hash at 3,113,400, 0 ERROR lines and no OOM kill; the cache-drop line once in each N run, never in S, N0 or B")
q, c = res[("1", "N0", "S", "ltop")][0], res[("1", "N0", "S", "cpu")][0]
say("H2", inb(q, 0.60, 0.90) and inb(c, 0.50, 0.85), "no cap: N0/S launch to top %s (band 0.60-0.90), CPU %s (band 0.50-0.85)" % (q, c))
q = res[("1", "N", "N0", "ltop")][0]
say("H3", inb(q, 0.95, 1.05), "no cap: N/N0 launch to top %s (band 0.95-1.05)" % q)
b2 = base["2"]
q, rr = res[("2", "N", b2, "ltop")][0], res[("2", "N", b2, "rate")][0]
say("H4", inb(q, 0.35, 0.70) and inb(rr, 1.6, 3.0), "1536M: N/%s launch to top %s (band 0.35-0.70), heavy rate %s (band 1.6-3.0)" % (b2, q, rr))
q, n = res[("2", "N0", b2, "ltop")][0], res[("2", "N", "N0", "ltop")][0]
say("H5", inb(q, 0.45, 0.90) and inb(n, 0.60, 1.00), "1536M: N0/%s launch to top %s (band 0.45-0.90), N/N0 %s (band 0.60-1.00)" % (b2, q, n))
bk, nk = arm("2", b2, kb), arm("2", "N", kb)
say("H6", bool(bk) and bool(nk) and min(bk) >= 100 and max(nk) <= 100, "1536M heavy reads kB/block: %s %s (at least 100), N %s (at most 100)" % (
    b2, [round(x, 1) for x in bk], [round(x, 1) for x in nk]))
nr = [g(r, "rss_anon_max_MB") for r in ok9]
say("H7", bool(nr) and max(nr) <= 800, "N and N0 peak RssAnon %s MB (at most 800 in every run)" % nr)
s2 = [r for r in allr if r["stage"] == "2" and r["arm"] == "S"]
say("H8", bool(s2) and all(r["f"].get("outcome") == "ok" and r["f"].get("cg_oom_kill") in ("0", "na") for r in s2),
    "stock fits under 1536M: S runs in stage 2: %s" % ["%s %s oom=%s" % (r["n"], r["f"].get("outcome"), r["f"].get("cg_oom_kill")) for r in s2])
print("stock's peak RssAnon (reported): " + str([(r["stage"], r["n"], g(r, "rss_anon_max_MB")) for r in allr if r["arm"] == "S"]))
